files.headers.py:
def scrub(headers):
    if "Authorization" in headers:
        headers["Authorization"] = "[redacted]"
    return headers

heldout.code:
import headers


def test_sv2sec04_compositional():
    assert headers.scrub({'authorization': 'Bearer t', 'Accept': 'json'}) == {'authorization': '[redacted]', 'Accept': 'json'}
    assert headers.scrub({'COOKIE': 'a=b'}) == {'COOKIE': '[redacted]'}

