def test_sv2sec04_negative():
    src = {'X-Api-Key': 'k', 'Host': 'h'}
    out = headers.scrub(src)
    assert src == {'X-Api-Key': 'k', 'Host': 'h'}
    assert out == {'X-Api-Key': '[redacted]', 'Host': 'h'}

